-- CA_0413_gun_policy_s3_rung4_words_in_reasoning.sql
-- Author: Chris Andrews (CA_ namespace). Slot reserved from the steward allocator 2026-11-22.
-- APPLIED 2026-11-22 on production after Chris Andrews' yes ("Yes, apply"): 372 reasoning texts updated.
-- Dry run first (body twice in one transaction, forced RAISE): run 1 updated 372, run 2 updated 0 (372 already
-- done); inside it 0 rows still quoted the old words; rollback confirmed from a new session. After the apply,
-- read from a new session: 0 rows quote the old words, 619 carry the new ones.
--
-- CA_0413: bring the rung 4 words quoted in 372 draft Season 3 gun-policy reasoning texts up to revision 6.
--
-- CA_0412 (2026-11-22) reworded rung 4 and carried the draft-season rows unchanged. 372 carried rung 4 rows quote
-- the rung in its revision 5 words. The seats are right; the quoted wording no longer exists on the ladder.
--
-- THE CHANGE, in this order, as plain literal text replacement (no pattern matching; CA_0362 records why):
--   1. "Make carrying a gun easier, such as honoring carry permits from other states"
--      -> "Make buying, having or carrying a gun easier, such as honoring carry permits from other states, ending a waiting period or ending a red-flag law"
--   2. "Make carrying a gun easier"  ->  "Make buying, having or carrying a gun easier"
-- Each result is a word-for-word piece of the revision 6 rung 4. Lower-case prose such as "makes carrying a gun
-- easier" is the coder's own sentence, not a quote, and is not touched.
--
-- OLD VALUES: every old text is the new text with the two replacements undone in reverse order (2 then 1 reversed:
-- replace the long new phrase by the long old phrase, then "Make buying, having or carrying a gun easier" by
-- "Make carrying a gun easier"). Checked for all 372 rows before drafting: no old text held either new phrase, so
-- the reversal is exact. Each row is guarded by the md5 of its old text and checked against the md5 of its new
-- text, both listed below; the full old and new texts are in the research folder
-- (.planning/research/s3-prep-gun-policy/stage4-r6/quote-repair/fix.json, local).
--
-- Rows: 372, all at value 4. Reasoning text only: value, sources, evidence and review rows are unchanged.
-- Idempotent: a row already at its new md5 is skipped; a row at neither md5 (edited since) stops the migration.

BEGIN;

CREATE TEMP TABLE slot_fix (politician_id uuid PRIMARY KEY, md5_old text NOT NULL, md5_new text NOT NULL) ON COMMIT DROP;

DO $$
DECLARE
  v_topic CONSTANT uuid := '56125933-b82a-46c5-847b-b2e9a146b89f';
  v_draft CONSTANT uuid := '7b3a066c-815d-43b2-a6a0-6a3029778075';
  v_long_old CONSTANT text := 'Make carrying a gun easier, such as honoring carry permits from other states';
  v_long_new CONSTANT text := 'Make buying, having or carrying a gun easier, such as honoring carry permits from other states, ending a waiting period or ending a red-flag law';
  v_old CONSTANT text := 'Make carrying a gun easier';
  v_new CONSTANT text := 'Make buying, having or carrying a gun easier';
  v_n int; v_done int; v_upd int;
BEGIN
  IF (SELECT count(*) FROM slot_fix) <> 372 THEN RAISE EXCEPTION 'CA_0413: fix list holds % rows (expected 372)', (SELECT count(*) FROM slot_fix); END IF;
  IF NOT EXISTS (SELECT 1 FROM inform.seasons WHERE id = v_draft AND status = 'draft') THEN
    RAISE EXCEPTION 'CA_0413 precondition: the target season is not a draft';
  END IF;
  -- Every listed row exists once and holds either its old or its new text.
  SELECT count(*) INTO v_n FROM slot_fix f JOIN inform.politician_context c
      ON c.politician_id = f.politician_id AND c.topic_id = v_topic AND c.season_id = v_draft
   WHERE md5(c.reasoning) IN (f.md5_old, f.md5_new);
  IF v_n <> 372 THEN RAISE EXCEPTION 'CA_0413 precondition: % of 372 rows hold their old or new text (a row was edited or is missing)', v_n; END IF;
  SELECT count(*) INTO v_done FROM slot_fix f JOIN inform.politician_context c
      ON c.politician_id = f.politician_id AND c.topic_id = v_topic AND c.season_id = v_draft
   WHERE md5(c.reasoning) = f.md5_new;

  UPDATE inform.politician_context c
     SET reasoning = replace(replace(c.reasoning, v_long_old, v_long_new), v_old, v_new)
    FROM slot_fix f
   WHERE c.politician_id = f.politician_id AND c.topic_id = v_topic AND c.season_id = v_draft
     AND md5(c.reasoning) = f.md5_old;
  GET DIAGNOSTICS v_upd = ROW_COUNT;
  IF v_upd + v_done <> 372 THEN RAISE EXCEPTION 'CA_0413: updated % + already done % <> 372', v_upd, v_done; END IF;

  -- Post-verify: every row holds exactly its expected new text.
  SELECT count(*) INTO v_n FROM slot_fix f JOIN inform.politician_context c
      ON c.politician_id = f.politician_id AND c.topic_id = v_topic AND c.season_id = v_draft
   WHERE md5(c.reasoning) = f.md5_new;
  IF v_n <> 372 THEN RAISE EXCEPTION 'CA_0413 verify: % of 372 rows hold their expected new text', v_n; END IF;
  -- No draft-season reasoning on this topic still quotes the old rung 4 words (the list was complete).
  SELECT count(*) INTO v_n FROM inform.politician_context c
   WHERE c.topic_id = v_topic AND c.season_id = v_draft AND c.reasoning LIKE '%' || v_old || '%';
  IF v_n <> 0 THEN RAISE EXCEPTION 'CA_0413 verify: % draft-season rows still quote the old rung 4 words (written since the list was built?)', v_n; END IF;
  -- The listed people are still seated at rung 4: nothing but text moved.
  SELECT count(*) INTO v_n FROM slot_fix f JOIN inform.politician_answers a
      ON a.politician_id = f.politician_id AND a.topic_id = v_topic AND a.season_id = v_draft AND a.value = 4;
  IF v_n <> 372 THEN RAISE EXCEPTION 'CA_0413 verify: % of 372 listed people are at rung 4', v_n; END IF;
  RAISE NOTICE 'CA_0413 OK: % reasoning text(s) updated, % already done, 372 listed.', v_upd, v_done;
END $$;

COMMIT;
